  8 /// Phase 2 UI/operations: the supervised worker profile seen from the Flutter UI.
  9 ///
 10 /// The frozen `WorkerPairedRuntime` (paired_runtime.dart, byte-identical to
 11 /// the Phase 1 checkpoint) spawns the frozen worker named by the manifest. This
 12 /// runtime spawns the Phase 2 COMPOSITION PROFILE (`scripts/run_uri_supervised_worker.py`)
 13 /// instead, speaks the same framed stdio protocol, and adds the execution
 14 /// lifecycle frames. It is an explicit, per-installation OPT-IN: the client
 15 /// root must hold `control/ui-supervised-profile.json`; nothing in a manifest
 16 /// or launcher is changed (no cutover). The UI never passes
 17 /// `--allow-fixture-qualification`, never sees tickets or credentials, and
 18 /// holds only execution ids: every state shown is re-read from the worker.
 19 const supervisedProfileFile = 'control/ui-supervised-profile.json';
 20 const supervisedProfileSchema = 'uri.phase2ops.ui_profile.v1';
 21 const supervisedWorkerProfile = 'phase2d-supervised';
 22 const supervisedWorkerEntrypoint = 'scripts/run_uri_supervised_worker.py';
