 26 // Tolerant readers: a damaged field in one worker record must never throw and hide the whole history/status
 27 // (review round 3, OPS-2R end to end). Anything of the wrong shape reads as null / empty.
 28 String? _str(dynamic v) => v is String ? v : null;
 29 bool? _bool(dynamic v) => v is bool ? v : null;
 30 double? _num(dynamic v) => v is num ? v.toDouble() : null;
 31 Map<String, dynamic>? _map(dynamic v) => v is Map ? v.cast<String, dynamic>() : null;
 32 List<Map<String, dynamic>> _maps(dynamic v) =>
 33     v is List ? v.whereType<Map>().map((m) => m.cast<String, dynamic>()).toList() : const [];
 34 const terminalExecutionStates = {'completed', 'failed', 'cancelled', 'uncertain', 'quota_paused'};
