256   Future<void> _cancel() async {
257     final current = _execution;
258     if (current == null) return;
259     setState(() => _busy = true);
260     try {
261       await _runtime!.cancelExecution(current.id);
262       await _refresh();
263       _pollWhileActive();
264     } catch (e) {
265       setState(() => _outcome = 'Cancel refused: $e');
266       await _refresh();
267     } finally {
268       if (mounted) setState(() => _busy = false);
269     }
270   }
